package tmmodern;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.resources.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.effect.*;import net.minecraft.server.level.*;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.event.TickEvent;import net.minecraftforge.registries.ForgeRegistries;import tc4revival.content.*;import tc4revival.research.*;
public class TMRuntime {
    private static final boolean APOTHEOSIS = net.minecraftforge.fml.ModList.get().isLoaded("apotheosis");
    private static final net.minecraft.tags.TagKey<net.minecraft.world.item.Item> STEP_BOOTS =
            net.minecraft.tags.ItemTags.create(net.minecraft.resources.ResourceLocation.parse("thaumcraft:traveller_step_boots"));

    public static Item item(String id){return ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(id));}public static Block block(String id){return ForgeRegistries.BLOCKS.getValue(ResourceLocation.parse(id));}
    public static void sound(Level l,BlockPos p,String id,float volume,float pitch){var s=ForgeRegistries.SOUND_EVENTS.getValue(ResourceLocation.parse(id));if(s!=null)l.playSound(null,p,s,net.minecraft.sounds.SoundSource.PLAYERS,volume,pitch);}
    public static net.minecraft.world.damagesource.DamageSource nightshade(Level l){return new net.minecraft.world.damagesource.DamageSource(l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,ResourceLocation.parse("taintedmagic:nightshade"))));}
    public static void effect(LivingEntity e,String effect,int ticks,int amplifier){var type=ForgeRegistries.MOB_EFFECTS.getValue(ResourceLocation.parse("thaumcraft:"+(effect.equals("taint_poison")?"flux_taint":effect)));if(type!=null)e.addEffect(new MobEffectInstance(type,ticks,amplifier));}
    public static void warp(Player p,int amount){if(p instanceof ServerPlayer s)KnowledgeSavedData.get(s.server).update(p.getUUID(),p.getRandom()::nextInt,k->{k.changeWarp(PlayerKnowledge.WarpKind.STICKY,amount);return null;});}
    public static boolean consumeInventory(Player p,Map<tc4revival.aspect.Aspect,Integer> cost,boolean commit){
        if(p.isCreative())return true;
        for(var s:WandInventory.wornBaubles(p))if(s.getItem() instanceof WandInventory.VisAmulet a&&a.consumeVis(s,p,cost,commit))return true;
        // The offhand is a separate inventory compartment, outside Inventory.items.
        // Include it in both the affordability check and the actual payment path.
        for(var compartment:List.of(p.getInventory().items,p.getInventory().offhand))
            for(var s:compartment)if(s.getItem() instanceof CastingWandItem w&&w.consumeForPlayer(s,p,cost,false,true,commit))return true;
        return false;
    }
    public static ItemStack curio(Player p,String id){return top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).resolve().flatMap(i->i.findFirstCurio(TaintedMagic.item(id))).map(r->r.stack()).orElse(ItemStack.EMPTY);}
    public static void setup(){TMProtection.setup();
        thaumcraft.api.research.ResearchPresentation.registerBackground("taintedmagic:background",0,"TAINTEDMAGIC",()->TMConfig.CUSTOM_BACKGROUND.get()?java.util.Optional.of("taintedmagic:textures/gui/gui_tm_researchback.png"):java.util.Optional.empty());for(String rod:List.of("taintedmagic:warpwood","taintedmagic:warpwood_staff"))thaumcraft.api.wands.WandRod.registerUpdate(rod,(stack,p)->{if(!(p instanceof ServerPlayer server)||p.hasEffect(TCEffects.WARP_WARD.get()))return;int warp=KnowledgeSavedData.get(server.server).snapshot(p.getUUID()).map(k->k.warp(PlayerKnowledge.WarpKind.PERMANENT)).orElse(0);if(warp<=0||p.tickCount%Math.max(1,Math.round(TMConfig.WARP_REFRESH.get()/(float)warp))!=0)return;var wand=(CastingWandItem)stack.getItem();for(String tag:List.of("aer","terra","ignis","aqua","ordo","perditio"))wand.addVis(stack,MagicFocus.aspect(tag),1,true,true);});TMEffects.register();}
    @SubscribeEvent public void tick(TickEvent.PlayerTickEvent event){if(event.phase!=TickEvent.Phase.END)return;Player p=event.player;var data=p.getPersistentData();boolean boots=p.getItemBySlot(EquipmentSlot.FEET).getItem() instanceof TMArmor.Boots;var sash=curio(p,"voidwalker_sash");boolean boost=boots&&!sash.isEmpty()&&TMCurio.speed(sash);
        if(boots && !(APOTHEOSIS && p.getItemBySlot(EquipmentSlot.FEET).is(STEP_BOOTS))){
            if(!data.contains("tmStep"))data.putFloat("tmStep",p.maxUpStep());
            p.setMaxUpStep(p.isShiftKeyDown()?data.getFloat("tmStep"):1);
        }else if(data.contains("tmStep")){p.setMaxUpStep(data.getFloat("tmStep"));data.remove("tmStep");}
        if(boots){if(p.fallDistance>3)p.fallDistance=1;if(p.zza>0&&(p.onGround()||p.getAbilities().flying)){float amount=.12f*(boost?2:1)*(p.getAbilities().flying?.75f:1);p.moveRelative(amount,new net.minecraft.world.phys.Vec3(0,0,1));}}
        if(p.level().isClientSide)return;
        var attack=p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE);
        var powerId=UUID.fromString("f4a4d9e6-0852-4e28-b344-b7906b5afc5d");
        var heldFocus=WandFocusItem.attached(p.getMainHandItem());
        double power=heldFocus.getItem() instanceof MagicFocus f&&f.kind.equals("mage_mace")?FocusPotency.bonus(p):0;
        var previous=attack.getModifier(powerId);
        if(previous!=null&&previous.getAmount()!=power)attack.removeModifier(powerId);
        if(power!=0&&attack.getModifier(powerId)==null)attack.addTransientModifier(new net.minecraft.world.entity.ai.attributes.AttributeModifier(powerId,"Mage mace potency",power,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));
        for(int i=0;i<p.getInventory().getContainerSize();i++){var s=p.getInventory().getItem(i);if(s.hasTag()&&s.getTag().getBoolean("voidtouched")&&s.isDamaged()&&p.tickCount%20==0)s.setDamageValue(s.getDamageValue()-1);}
        boolean lumos=!curio(p,"lumos_ring").isEmpty();for(var s:List.of(p.getMainHandItem(),p.getOffhandItem()))if(WandFocusItem.attached(s).getItem() instanceof MagicFocus f&&f.kind.equals("lumos"))lumos=true;
        if(lumos){if(!p.hasEffect(MobEffects.NIGHT_VISION)||data.getBoolean("tmNight")){p.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION,260,0,false,false));data.putBoolean("tmNight",true);}}else if(data.getBoolean("tmNight")){var active=p.getEffect(MobEffects.NIGHT_VISION);if(active!=null&&active.getDuration()<=260&&!active.isVisible())p.removeEffect(MobEffects.NIGHT_VISION);data.remove("tmNight");}
        boolean charm=java.util.stream.IntStream.range(0,p.getInventory().getContainerSize()).anyMatch(slot->p.getInventory().getItem(slot).is(TaintedMagic.item("flyte_charm"))),hasVis=charm&&consumeInventory(p,Map.of(MagicFocus.aspect("aer"),15),false);
        if(hasVis){if(!p.getAbilities().mayfly){p.getAbilities().mayfly=true;data.putBoolean("tmFlight",true);p.onUpdateAbilities();}if(p.getAbilities().flying)consumeInventory(p,Map.of(MagicFocus.aspect("aer"),15),true);else if(p.isShiftKeyDown()&&!p.onGround()&&p.fallDistance>.5&&consumeInventory(p,Map.of(MagicFocus.aspect("aer"),5),true)){double yaw=Math.toRadians(p.getYHeadRot()+90);p.setDeltaMovement(p.getDeltaMovement().x+Math.cos(yaw)*.1,-.1,p.getDeltaMovement().z+Math.sin(yaw)*.1);p.hurtMarked=true;}}
        else if(data.getBoolean("tmFlight")){if(!p.isCreative()&&!p.isSpectator()){p.getAbilities().mayfly=false;p.getAbilities().flying=false;p.onUpdateAbilities();}data.remove("tmFlight");}
    }
    @SubscribeEvent public void jump(net.minecraftforge.event.entity.living.LivingEvent.LivingJumpEvent event){if(event.getEntity() instanceof Player p){var sash=curio(p,"voidwalker_sash");double multiplier=(p.getItemBySlot(EquipmentSlot.FEET).getItem() instanceof TMArmor.Boots?1.25:1)*(!sash.isEmpty()&&TMCurio.speed(sash)?1.05:1);p.setDeltaMovement(p.getDeltaMovement().multiply(1,multiplier,1));}}
    @SubscribeEvent public void fall(net.minecraftforge.event.entity.living.LivingFallEvent event){if(event.getEntity().getItemBySlot(EquipmentSlot.FEET).getItem() instanceof TMArmor.Boots){event.setCanceled(true);}}
    @SubscribeEvent public void attributes(net.minecraftforge.event.ItemAttributeModifierEvent event){if(event.getSlotType()!=EquipmentSlot.MAINHAND)return;var stack=event.getItemStack();var attached=WandFocusItem.attached(stack);if(attached.getItem() instanceof MagicFocus f&&f.kind.equals("mage_mace")&&stack.getItem() instanceof CastingWandItem wand){for(var existing:java.util.List.copyOf(event.getModifiers().get(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)))if(existing.getId().equals(UUID.fromString("cb3f55d3-645c-4f38-a497-9c13a33db5cf")))event.removeModifier(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE,existing);event.addModifier(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE,new net.minecraft.world.entity.ai.attributes.AttributeModifier(UUID.fromString("4b3b80b6-8d2c-4ef7-8f2e-8ad8fa2f6502"),"Mage mace",TMConfig.MACE_DAMAGE.get()+wand.focusUpgrade(stack,FocusUpgrade.POTENCY)+(wand.isStaff(stack)?5:0),net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADDITION));}}
    @SubscribeEvent public void attack(net.minecraftforge.event.entity.living.LivingAttackEvent event){if(event.getSource().getDirectEntity() instanceof Player p&&event.getSource().is(net.minecraft.world.damagesource.DamageTypes.PLAYER_ATTACK)){var wand=p.getMainHandItem();var attached=WandFocusItem.attached(wand);if(attached.getItem() instanceof MagicFocus f&&f.kind.equals("mage_mace")&&!MagicFocus.pay(wand,p,f.costs(attached)))event.setCanceled(true);}}
    @SubscribeEvent public void crafted(net.minecraftforge.event.entity.player.PlayerEvent.ItemCraftedEvent event){if(event.getCrafting().is(TaintedMagic.item("shard_of_creation"))&&event.getEntity() instanceof ServerPlayer p){boolean unlocked=KnowledgeSavedData.get(p.server).update(p.getUUID(),p.getRandom()::nextInt,k->{if(!k.researchMarkers().contains("taintedmagic:CREATIONSHARD")||k.researchMarkers().contains("taintedmagic:CREATION"))return false;k.rememberResearch("taintedmagic:CREATION");k.rememberResearch("OUTERREV");return true;});if(unlocked){p.displayClientMessage(net.minecraft.network.chat.Component.translatable("text.creation"),true);p.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,200,0));sound(p.level(),p.blockPosition(),"thaumcraft:egidle",1,1);sound(p.level(),p.blockPosition(),"thaumcraft:heartbeat",1,1);}}}
    @SubscribeEvent public void tooltip(net.minecraftforge.event.entity.player.ItemTooltipEvent event){if(event.getItemStack().hasTag()&&event.getItemStack().getTag().getBoolean("voidtouched"))event.getToolTip().add(net.minecraft.network.chat.Component.translatable("text.voidtouched").withStyle(net.minecraft.ChatFormatting.DARK_PURPLE));}
    public static void saltTick(net.minecraft.world.entity.item.ItemEntity drop,UtilityItem utility){if(!(drop.level() instanceof ServerLevel l))return;int age=drop.getAge();if(age>=100){if(utility.kind.equals("salis_tempestas")){boolean rain=!l.isRaining();l.setWeatherParameters(rain?0:24000,24000,rain,rain&&l.random.nextInt(10)==0);}else{long time=l.getDayTime(),day=Math.floorDiv(time,24000)*24000,phase=Math.floorMod(time,24000);l.setDayTime(phase<12000?day+14000:day+24000);}TMRuntime.sound(l,drop.blockPosition(),"thaumcraft:ice",.3f,1+l.random.nextFloat()*.25f);TMEffects.sparkles(l,drop.position().add(0,drop.getBbHeight(),0),200,utility.kind.equals("salis_tempestas")?7:6,1.75f,-.1f);drop.discard();}else{TMEffects.sparkles(l,drop.position().add(0,drop.getBbHeight(),0),1,utility.kind.equals("salis_tempestas")?7:6,1.75f,-.1f);if(age%30==0)sound(l,drop.blockPosition(),"thaumcraft:wind",.1f,1);}}
}
